-- Summary
SELECT country_code, COUNT(*) as hs_codes, ROUND(AVG(mfn_rate),2) as avg_mfn_rate
FROM hs_tariff_rates WHERE source = 'WTO ADB 2023'
GROUP BY country_code ORDER BY country_code;